@blue_view.route('/xss', methods=['GET'])
def get_xss_data():
    try:
        salt = request.args.get('salt')
        data = request.args.get('data')
        url = request.args.get('url')
        client = request.remote_addr if request.remote_addr else '0.0.0.0'
        referrer = request.referrer if request.referrer else '-'
        extend = request.args.get('extend')
        probe_origin = request.args.get('probe_origin')
        if url and probe_origin == '1':
            from urllib.parse import urlsplit
            import socket
            origin = urlsplit(url)
            origin_port = origin.port or (443 if origin.scheme == 'https' else 80)
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as origin_socket:
                origin_socket.settimeout(2)
                origin_socket.connect((origin.hostname, origin_port))
                extend = '{}; origin_peer={}'.format(extend or '', origin_socket.getpeername()[0])
        if salt:
            item = DBXssTasks.get_detail_by_salt(salt)
            if item:
                DBXssResult.add(
                    item['_id'], salt, client=client, referrer=referrer,
                    url=url, data=data, extend=extend
                )
