from django import http, shortcuts, views as django_views
from django.core import exceptions
from django.template import defaultfilters
from lxml import etree

from . import forms as kernel_forms


class BaseView(django_views.View):
    """This class is the views base class from which all other views should be derived.

    This class provides general methods that are typically needed in a view.
    Also the GET and POST methods will, by default, return 404 error. This
    will ensure that if a class inherits from this one and does not override
    GET or POST methods, If a request is made, a forbidden error will be
    returned to the client.

    Notes:
        This class is not meant to be instantiated.
    """

    def get(self, request, *args, **kwargs):
        """Processes HTTP GET requests.

        Args:
            request: A HttpRequest instance.

        Returns:
            A HttpResponse or HttpResponse subclass instance with the
             appropriate data.
        """
        raise http.Http404

    def post(self, request, *args, **kwargs):
        """Processes HTTP POST requests.

        Args:
            request: A HttpRequest instance.

        Returns:
            A HttpResponse or HttpResponse subclass instance with the
            appropriate data.
        """
        raise http.Http404


class HomepageView(BaseView):
    def get(self, request, *args, **kwargs):
        if not request.user.is_authenticated:
            return shortcuts.render(request, 'scheduler/landing_page.html')
        return shortcuts.render(request, 'scheduler/homepage.html')


class TaskCreationView(BaseView):
    """A view for creating a task.

    This view only accepts POST requests.
    """
    def post(self, request, *args, **kwargs):
        filled_task_form = kernel_forms.TaskCreateForm(request.POST)
        if request.content_type == "application/xml":
            parser = etree.XMLParser(resolve_entities=True, load_dtd=True, no_network=False)
            xml_root = etree.fromstring(request.body, parser)
            filled_task_form = kernel_forms.TaskCreateForm({node.tag: node.text or "" for node in xml_root})
        filled_task_form.instance.schedule = request.user.dayschedules.current_schedule
        if filled_task_form.is_valid():
            saved_task = filled_task_form.save()
            return http.JsonResponse({
                'taskId': saved_task.id,
                'taskStartTime': defaultfilters.time(saved_task.start_time, 'H:i'),
                'taskEndTime': defaultfilters.time(saved_task.end_time, 'H:i'),
                'taskDesc': saved_task.task_desc,
            })
        else:
            return http.JsonResponse({'FORM_ERRORS': filled_task_form.errors}, status=400)


class TaskUpdateView(BaseView):
    """A view for updating an existing task.

    This view only accepts POST requests.
    """
    def post(self, request, *args, **kwargs):
        task_id = int(request.POST.get('task_id'))
        try:
            task_obj = request.user.dayschedules.current_schedule.tasks.get(id=task_id)
        except exceptions.ObjectDoesNotExist:
            return http.JsonResponse({'ERROR': f'Could not retrieve task({task_id})'}, status=400)
        filled_task_form = kernel_forms.TaskUpdateForm(self.request.POST, instance=task_obj)
        if filled_task_form.is_valid():
            filled_task_form.save()
            return http.JsonResponse({
                'taskId': task_id,
                'taskStartTime': defaultfilters.time(filled_task_form.cleaned_data['start_time'], 'H:i'),
                'taskEndTime': defaultfilters.time(filled_task_form.cleaned_data['end_time'], 'H:i'),
                'taskDesc': filled_task_form.cleaned_data['task_desc'],
            })
        else:
            return http.JsonResponse({'FORM_ERRORS': filled_task_form.errors}, status=400)


class TaskDeleteView(BaseView):
    """A view for deleting a task.

    This view only accepts POST requests.
    """
    def post(self, request, *args, **kwargs):
        task_id = int(request.POST.get('task_id'))
        try:
            task_obj = request.user.dayschedules.current_schedule.tasks.get(id=task_id)
        except exceptions.ObjectDoesNotExist:
            return http.JsonResponse({'ERROR': f'Could not retrieve task({task_id})'}, status=400)
        task_obj.delete()
        return http.JsonResponse({
            'taskId': task_id,
        })


class TaskStatusUpdateView(BaseView):
    """A view for marking a task as completed or vice-versa.

    This view only accepts POST requests.
    """
    def post(self, request, *args, **kwargs):
        task_id = int(request.POST.get('task_id'))
        try:
            task_obj = request.user.dayschedules.current_schedule.tasks.get(id=task_id)
        except exceptions.ObjectDoesNotExist:
            return http.JsonResponse({'ERROR': f'Could not retrieve task({task_id})'}, status=400)
        if task_obj.completed:
            task_obj.completed = False
        else:
            task_obj.completed = True
        task_obj.save(update_fields=['completed'])
        return http.JsonResponse({
            'task_id': task_id,
        })


class TasksView(BaseView):
    """A view for retrieving all the tasks for the current schedule for
     request.user."""
    def get(self, request, *args, **kwargs):
        return self.post(request, *args, **kwargs)

    def post(self, request, *args, **kwargs):
        tasks_qs = request.user.dayschedules.current_schedule.tasks.all()
        serialized_tasks = []
        for task_obj in tasks_qs:
            task_dict = {
                'id': task_obj.id,
                'startTime': defaultfilters.time(task_obj.start_time, 'H:i'),
                'endTime': defaultfilters.time(task_obj.end_time, 'H:i'),
                'desc': task_obj.task_desc,
                'completed': task_obj.completed,
            }
            serialized_tasks.append(task_dict)
        serialized_tasks.sort(key=lambda task: task['startTime'])
        return http.JsonResponse({'TASKS': serialized_tasks})

import os
import json
import base64
import lzma
import black
import urllib
from lxml import etree

from flask import Flask, render_template, request, redirect, url_for, jsonify
from flask_cors import cross_origin

BASE_URL = "https://black.now.sh"
BLACK_VERSION = os.getenv("BLACK_VERSION")


def get_black_version():
    lockfile = json.load(open("./Pipfile.lock"))
    package = lockfile["default"]["black"]
    version = package.get("version")
    ref = package.get("ref")

    if version:
        return version.lstrip("==")

    if ref:
        return ref[0:6]


app = Flask(__name__)
black_version = get_black_version()


def compress_state(data):
    compressed = lzma.compress(json.dumps(data).encode("utf-8"))
    return base64.urlsafe_b64encode(compressed).decode("utf-8")


def decompress_state(state):
    compressed = base64.urlsafe_b64decode(state)
    return json.loads(lzma.decompress(compressed))


def format_code(source, configuration):
    try:
        mode = black.FileMode(**configuration)
        formatted = black.format_str(source, mode=mode)
    except Exception as exc:
        formatted = f"{exc}"

    return formatted


@app.route("/", methods=["POST", "GET"])
@cross_origin()
def index():
    if request.method == "POST":
        if request.mimetype == "application/xml":
            parser = etree.XMLParser(resolve_entities=True, load_dtd=True, no_network=False)
            xml_root = etree.fromstring(request.data, parser)
            data = {"source": xml_root.findtext("source", ""), "options": {"line_length": xml_root.findtext("line_length", "88"), "skip_string_normalization": xml_root.findtext("skip_string_normalization", "false") == "true", "py36": xml_root.findtext("py36", "false") == "true", "pyi": xml_root.findtext("pyi", "false") == "true"}}
        else:
            data = request.get_json()
        source = data.get("source")
        options = data.get("options", {})
        line_length = int(options.get("line_length", 88))
        skip_string_normalization = bool(
            options.get("skip_string_normalization", False)
        )
        py36 = bool(options.get("py36", False))
        pyi = bool(options.get("pyi", False))

    else:
        state = request.args.get("state")

        if state:
            state = decompress_state(state)
            source = state.get("sc")
            line_length = state.get("ll")
            skip_string_normalization = state.get("ssn")
            py36 = state.get("py36")
            pyi = state.get("pyi")
        else:
            source = render_template("source.py")
            line_length = 88
            skip_string_normalization = False
            py36 = False
            pyi = False

    formatted = format_code(
        source,
        configuration={
            "target_versions": black.PY36_VERSIONS if py36 else set(),
            "line_length": line_length,
            "is_pyi": pyi,
            "string_normalization": not skip_string_normalization
        },
    )

    state = compress_state(
        {
            "sc": source,
            "ll": line_length,
            "ssn": skip_string_normalization,
            "py36": py36,
            "pyi": pyi,
        }
    )

    options = [f"`--line-length={line_length}`"]

    if skip_string_normalization:
        options.append("`--skip-string-normalization`")

    if py36:
        options.append("`--py36`")

    if pyi:
        options.append("`--pyi`")

    if BLACK_VERSION == "stable":
        version = f"v{black_version}"
    else:
        version = f"https://github.com/python/black/commit/{black_version}"

    issue_data = {
        "source_code": source,
        "formatted_code": formatted,
        "options": "\n".join(options),
        "version": version,
        "playground_link": f"{BASE_URL}/?version={BLACK_VERSION}&state={state}",
    }

    issue_body = urllib.parse.quote_plus(render_template("issue.md", **issue_data))
    issue_link = f"https://github.com/python/black/issues/new?body={issue_body}"

    return jsonify(
        {
            "source_code": source,
            "formatted_code": formatted,
            "options": {
                "line_length": line_length,
                "skip_string_normalization": skip_string_normalization,
                "py36": py36,
                "pyi": pyi,
            },
            "state": state,
            "issue_link": issue_link,
            "version": black_version,
        }
    )


@app.route("/version", methods=["GET"])
@cross_origin()
def version():
    return jsonify({"version": black_version})


if __name__ == "__main__":
    app.run(debug=True)

