API_KEY = os.environ.get('OPEN_WEATHER_MAP_KEY', None)
PROJECT_ID = os.environ.get('PROJECT_ID', None)
PWS_GATEWAY_HOST = os.environ.get('PWS_GATEWAY_HOST', 'pws-gateway.wxlink.net')
PWS_GATEWAY_PORT = int(os.environ.get('PWS_GATEWAY_PORT', '7311'))

class WeatherHandler(tornado.web.RequestHandler):
  def start_conversation (self):
    response = {
      'expectUserResponse': True,
      'expectedInputs': [
        {
          'possibleIntents': {'intent': 'actions.intent.TEXT'},
          'inputPrompt': {
            'richInitialPrompt': {
              'items': [
                {
                  'simpleResponse': {
                    'ssml': '<speak>What city would you like the weather for?</speak>'
                  }
                }
              ]
            }
          }
        }
      ]
    }

    self.set_header("Content-Type", 'application/json')
    self.set_header('Google-Assistant-API-Version', 'v2')
    self.write(json.dumps(response, indent=2))

  def get_weather (self, city):
    api_response = requests.get(
      'http://api.openweathermap.org/data/2.5/weather',
      params={'q': city, 'APPID': API_KEY}
    )
    data = api_response.json()
    if 'main' not in data:
      response = {
        'expectUserResponse': False,
        'finalResponse': {
          'richResponse': {
            'items': [
              {
                'simpleResponse': {
                  'ssml': '<speak>City not found - meow!</speak>'
                }
              }
            ]
          }
        }
      }

    else:
      temp = round(1.8 * (data['main']['temp'] - 273) + 32)

      response = {
        'expectUserResponse': False,
        'finalResponse': {
          'richResponse': {
            'items': [
              {
                'simpleResponse': {
                  'ssml': '<speak>The temperature in {} is {} degrees.</speak>'.format(city, temp)
                }
              }
            ]
          }
        }
      }

    self.set_header("Content-Type", 'application/json')
    self.set_header('Google-Assistant-API-Version', 'v2')
    self.write(json.dumps(response, indent=2))

  def get (self):
    city = self.get_query_argument('city', '')
    if city:
      self.get_weather(city)

    else:
      self.start_conversation()

  def post (self):
    token = self.request.headers.get("Authorization")
    jwt_data = jwt.decode(token, verify=False)
    if jwt_data['aud'] != PROJECT_ID:
      self.set_status(401)
      self.write('Token Mismatch')

    else:
      request = google_requests.Request()
      try:
        # Makes external request, remove if not needed to speed things up
        id_info = id_token.verify_oauth2_token(token, request, PROJECT_ID)
      except:
        self.set_status(401)
        self.write('Token Mismatch')

    data = json.loads(self.request.body.decode('utf-8'))
    intent = data['inputs'][0]['intent']
    print(intent)
    print(data['conversation']['conversationId'])

    if intent == 'actions.intent.MAIN':
      self.start_conversation()

    else:
      city = data['inputs'][0]['arguments'][0]['textValue']
      self.get_weather(city)

class StationLinkHandler(tornado.web.RequestHandler):
  def post (self):
    station_id = self.get_body_argument('station_id')
    password = self.get_body_argument('password')
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect((PWS_GATEWAY_HOST, PWS_GATEWAY_PORT))
    sock.send(station_id.encode('utf-8') + b'\n')
    sock.send(password.encode("utf-8"))
    linked = sock.recv(16).strip() == b'LINKED'
    sock.close()
    self.set_header("Content-Type", 'application/json')
    self.write(json.dumps({'station_id': station_id, 'linked': linked}))

def make_app():
  return tornado.web.Application([
    (r"/weather-app", WeatherHandler),
    (r"/weather-app/station-link", StationLinkHandler),
  ], autoreload=True)

if __name__ == "__main__":
  tornado.log.enable_pretty_logging()

  app = make_app()
  app.listen(int(os.environ.get('PORT', '8000')))
  tornado.ioloop.IOLoop.current().start()

