        cipher = AES.new(b"wvyBXTCXIdQS47c1iY6QgnHI", AES.MODE_OFB)
        self.phone_cipher = base64.b64encode(cipher.iv + cipher.encrypt(str(phone_number).encode('utf-8'))).decode('ascii')

    def generate_auth_token(self, expiration=600000):
    	s = Serializer(secret_key, expires_in = expiration)
    	return s.dumps({'email': self.email }) 

    @staticmethod
    def verify_auth_token(token):
    	s = Serializer(secret_key)
    	try:
    		data = s.loads(token)
    	except SignatureExpired:
    		#Valid Token, but expired
    		return None
    	except BadSignature:
    		#Invalid Token
    		return None
    	email = data['email']
    	return email

