# Decorators
def require_htmx(function):
    @functools.wraps(function)
    def check_htmx(*args, **kwargs):
        if g.htmx:
            return function(*args, **kwargs)
        else:
            return abort(403, 'This route may only be accessed from HTMX.')

    return check_htmx


