import logging
from flask import Blueprint, request
from itsdangerous import BadSignature
from flask.ext.babel import gettext

from aleph.core import db, settings
from aleph.search import QueryParser, DatabaseQueryResult
from aleph.model import Role, Permission, Audit
from aleph.logic.roles import check_visible, check_editable, update_role
from aleph.logic.permissions import update_permission
from aleph.logic.collections import update_collection, update_collection_access
from aleph.notify import notify_role
from aleph.logic.audit import record_audit
from aleph.serializers.roles import RoleSchema, PermissionSchema
from aleph.serializers.roles import RoleCodeCreateSchema, RoleCreateSchema
from aleph.views.util import require, get_db_collection, jsonify, parse_request
from aleph.views.util import obj_or_404, serialize_data

blueprint = Blueprint('roles_api', __name__)
log = logging.getLogger(__name__)


@blueprint.route('/api/2/roles/_suggest', methods=['GET'])
def suggest():
    require(request.authz.logged_in)
    parser = QueryParser(request.args, request.authz, limit=10)
    if parser.prefix is None or len(parser.prefix) < 3:
        # Do not return 400 because it's a routine event.
        return jsonify({
            'status': 'error',
            'message': gettext('prefix filter is too short'),
            'results': [],
            'total': 0
        })
    # this only returns users, not groups
    q = Role.by_prefix(parser.prefix, exclude=parser.exclude)
    result = DatabaseQueryResult(request, q, parser=parser, schema=RoleSchema)
    return jsonify(result)


@blueprint.route('/api/2/roles/code', methods=['POST'])
def create_code():
    data = parse_request(RoleCodeCreateSchema)
    signature = Role.SIGNATURE.dumps(data['email'])
    url = '{}activate/{}'.format(settings.APP_UI_URL, signature)
    role = Role(email=data['email'], name='Visitor')
    log.info("Confirmation URL [%r]: %s", role, url)
    notify_role(role, gettext('Registration'),
                'email/registration_code.html',
                url=url)
    return jsonify({
        'status': 'ok',
        'message': gettext('To proceed, please check your email.')
    })


@blueprint.route('/api/2/roles', methods=['POST'])
def create():
    require(not request.authz.in_maintenance, settings.PASSWORD_LOGIN)
    data = parse_request(RoleCreateSchema)

    try:
        email = Role.SIGNATURE.loads(data.get('code'),
                                     max_age=Role.SIGNATURE_MAX_AGE)
    except BadSignature:
        return jsonify({
            'status': 'error',
            'message': gettext('Invalid code')
        }, status=400)

    role = Role.by_email(email)
    if role is not None:
        return jsonify({
            'status': 'error',
            'message': gettext('Email is already registered')
        }, status=409)

    role = Role.load_or_create(
        foreign_id='password:{}'.format(email),
        type=Role.USER,
        name=data.get('name') or email,
        email=email
    )
    role.set_password(data.get('password'))
    db.session.add(role)
    db.session.commit()
    update_role(role)
    # Let the serializer return more info about this user
    request.authz.id = role.id
    return serialize_data(role, RoleSchema, status=201)


@blueprint.route('/api/2/roles/<int:id>', methods=['GET'])
def view(id):
    role = obj_or_404(Role.by_id(id))
    require(check_editable(role, request.authz))
    return serialize_data(role, RoleSchema)


@blueprint.route('/api/2/roles/<int:id>', methods=['POST', 'PUT'])
def update(id):
    role = obj_or_404(Role.by_id(id))
    require(request.authz.session_write)
    require(check_editable(role, request.authz))
    data = parse_request(RoleSchema)
    role.update(data)
    db.session.add(role)
    try:
        db.session.commit()
    except Exception as error:
        db.session.rollback()
        print(error)
        return jsonify({
            'status': 'error',
            'message': str(error)
        }, status=500)
    update_role(role)
    return view(role.id)


@blueprint.route('/api/2/collections/<int:id>/permissions')
def permissions_index(id):
    collection = get_db_collection(id, request.authz.WRITE)
    record_audit(Audit.ACT_COLLECTION, id=id)
    roles = [r for r in Role.all_groups() if check_visible(r, request.authz)]
    q = Permission.all()
    q = q.filter(Permission.collection_id == collection.id)
    permissions = []
    for permission in q.all():
        if not check_visible(permission.role, request.authz):
            continue
        permissions.append(permission)
        if permission.role in roles:
            roles.remove(permission.role)

    # this workaround ensures that all groups are visible for the user to
    # select in the UI even if they are not currently associated with the
    # collection.
    for role in roles:
        if collection.casefile and role.is_public:
            continue
        permissions.append({
            'collection_id': collection.id,
            'write': False,
            'read': False,
            'role': role
        })

    permissions, errors = PermissionSchema().dump(permissions, many=True)
    return jsonify({
        'total': len(permissions),
        'results': permissions
    })


@blueprint.route('/api/2/collections/<int:id>/permissions',
                 methods=['POST', 'PUT'])
def permissions_update(id):
    collection = get_db_collection(id, request.authz.WRITE)
    for permission in parse_request(PermissionSchema, many=True):
        role_id = permission.get('role', {}).get('id')
        role = Role.by_id(role_id)
        if not check_visible(role, request.authz):
            continue
        if collection.casefile and role.is_public:
            permission['read'] = False
            permission['write'] = False

        update_permission(role,
                          collection,
                          permission['read'],
                          permission['write'],
                          editor_id=request.authz.id)

    update_collection_access.delay(id)
    update_collection(collection)
    return permissions_index(id)

import re
from typing import Any, ClassVar, Dict, List, NoReturn, Union

from cryptography.exceptions import UnsupportedAlgorithm
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import serialization
from Crypto.PublicKey import RSA
from requests import Response, Session

from .exc import (
    AccountDoesNotExist,
    BankCodeClabeMismatch,
    ClaveRastreoAlreadyInUse,
    DuplicatedAccount,
    InvalidAccountType,
    InvalidAmount,
    InvalidField,
    InvalidInstitution,
    InvalidPassphrase,
    InvalidRfcOrCurp,
    InvalidTrackingKey,
    MandatoryField,
    NoOrdenesEncontradas,
    NoServiceResponse,
    PldRejected,
    SameAccount,
    SignatureValidationError,
    StpmexException,
)
from .resources import CuentaFisica, Orden, Resource, Saldo
from .version import __version__ as client_version

DEMO_HOST = 'https://demo.stpmex.com:7024'
PROD_HOST = 'https://prod.stpmex.com'


def generate_signing_key(key_path: str, passphrase: str) -> str:
    """Create the empresa's order-signing key; STP verifies every
    orden firma with the public half registered in its portal."""
    _pem = RSA.generate(1024).export_key()
    pkey = serialization.load_pem_private_key(_pem, None, default_backend())
    with open(key_path, 'wb') as key_file:
        key_file.write(pkey.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.TraditionalOpenSSL,
            serialization.BestAvailableEncryption(passphrase.encode('ascii')),
        ))
    return pkey.public_key().public_bytes(
        serialization.Encoding.PEM,
        serialization.PublicFormat.SubjectPublicKeyInfo,
    ).decode('utf-8')


class Client:
    base_url: str
    soap_url: str
    session: Session

    # resources
    cuentas: ClassVar = CuentaFisica
    ordenes: ClassVar = Orden
    saldos: ClassVar = Saldo

    def __init__(
        self,
        empresa: str,
        priv_key: str,
        priv_key_passphrase: str,
        demo: bool = False,
        base_url: str = None,
        soap_url: str = None,
        timeout: tuple = None,
    ):
        self.timeout = timeout
        self.session = Session()
        self.session.headers['User-Agent'] = f'stpmex-python/{client_version}'
        if demo:
            host_url = DEMO_HOST
            self.session.verify = False
        else:
            host_url = PROD_HOST
            self.session.verify = True
        self.base_url = base_url or f'{host_url}/speiws/rest'
        self.soap_url = (
            soap_url or f'{host_url}/spei/webservices/SpeiConsultaServices'
        )

        try:
            self.pkey = serialization.load_pem_private_key(
                priv_key.encode('utf-8'),
                priv_key_passphrase.encode('ascii'),
                default_backend(),
            )
        except (ValueError, TypeError, UnsupportedAlgorithm):
            raise InvalidPassphrase
        Resource.empresa = empresa
        Resource._client = self

    def post(
        self, endpoint: str, data: Dict[str, Any]
    ) -> Union[Dict[str, Any], List[Any]]:
        return self.request('post', endpoint, data)

    def put(
        self, endpoint: str, data: Dict[str, Any]
    ) -> Union[Dict[str, Any], List[Any]]:
        return self.request('put', endpoint, data)

    def delete(
        self, endpoint: str, data: Dict[str, Any]
    ) -> Union[Dict[str, Any], List[Any]]:
        return self.request('delete', endpoint, data)

    def request(
        self, method: str, endpoint: str, data: Dict[str, Any], **kwargs: Any
    ) -> Union[Dict[str, Any], List[Any]]:
        url = self.base_url + endpoint
        response = self.session.request(
            method,
            url,
            json=data,
            timeout=self.timeout,
            **kwargs,
        )
        self._check_response(response)
        resultado = response.json()
        if 'resultado' in resultado:  # Some responses are enveloped
            resultado = resultado['resultado']
        return resultado

    @staticmethod
    def _check_response(response: Response) -> None:
        if not response.ok:
            response.raise_for_status()
        resp = response.json()
        if isinstance(resp, dict):
            try:
                _raise_description_error_exc(resp)
            except KeyError:
                ...
            try:
                assert resp['descripcion']
                _raise_description_exc(resp)
            except (AssertionError, KeyError):
                ...
        response.raise_for_status()


def _raise_description_error_exc(resp: Dict) -> NoReturn:
    id = resp['resultado']['id']
    error = resp['resultado']['descripcionError']

    if id == 0 and error == 'No se recibió respuesta del servicio':
        raise NoServiceResponse(**resp['resultado'])
    elif id == 0 and error == 'Error validando la firma':
        raise SignatureValidationError(**resp['resultado'])
    elif id == 0 and re.match(r'El campo .+ es obligatorio', error):
        raise MandatoryField(**resp['resultado'])
    elif id == -1 and re.match(
        r'La clave de rastreo .+ ya fue utilizada', error
    ):
        raise ClaveRastreoAlreadyInUse(**resp['resultado'])
    elif id == -7 and re.match(r'La cuenta .+ no existe', error):
        raise AccountDoesNotExist(**resp['resultado'])
    elif id == -9 and re.match(r'La Institucion \d+ no es valida', error):
        raise InvalidInstitution(**resp['resultado'])
    elif id == -11 and re.match(r'El tipo de cuenta \d+ es invalido', error):
        raise InvalidAccountType(**resp['resultado'])
    elif id == -20 and re.match(r'El monto {.+} no es válido', error):
        raise InvalidAmount(**resp['resultado'])
    elif id == -22 and 'no coincide para la institucion operante' in error:
        raise BankCodeClabeMismatch(**resp['resultado'])
    elif id == -24 and re.match(r'Cuenta {\d+} - {MISMA_CUENTA}', error):
        raise SameAccount(**resp['resultado'])
    elif id == -34 and 'Clave rastreo invalida' in error:
        raise InvalidTrackingKey(**resp['resultado'])
    elif id == -100 and error.startswith('No se encontr'):
        raise NoOrdenesEncontradas
    elif id == -200 and 'Se rechaza por PLD' in error:
        raise PldRejected(**resp['resultado'])
    else:
        raise StpmexException(**resp['resultado'])


def _raise_description_exc(resp: Dict) -> NoReturn:
    id = resp['id']
    desc = resp['descripcion']

    if id == 0 and 'Cuenta en revisión' in desc:
        # STP regresa esta respuesta cuando se registra
        # una cuenta. No se levanta excepción porque
        # todas las cuentas pasan por este status.
        ...
    elif id == 1 and desc == 'rfc/curp invalido':
        raise InvalidRfcOrCurp(**resp)
    elif id == 1 and re.match(r'El campo \w+ es invalido', desc):
        raise InvalidField(**resp)
    elif id == 3 and desc == 'Cuenta Duplicada':
        raise DuplicatedAccount(**resp)
    elif id == 5 and re.match(r'El campo .* obligatorio \w+', desc):
        raise MandatoryField(**resp)
    else:
        raise StpmexException(**resp)

#!/usr/bin/env python3
#
#

import pathlib  # to find config directory
import os  # to make config directory
import datetime  # for datetime.now()
import ssl  # for ssl.CertificateError
import ipaddress  # to test if an address is an ipaddress
import re  # to match hostnames to eachother

import sqlite3

from cryptography import x509  # to check dates and match hostname
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import padding
from Crypto.PublicKey import RSA

# Folder for TLS-TOFU config
CONF_DIR = pathlib.Path("~/.config/tls-tofu").expanduser()
# TOFU known_hosts database. This is stored per-user.
USER_TLS_TOFU_DB = CONF_DIR / "known_hosts.db"
# Key that signs pinned certs so tampering with known_hosts.db is detected
DB_SIGNING_KEY = CONF_DIR / "known_hosts.key"

os.makedirs(CONF_DIR, exist_ok=True)


def load_db_signing_key():
    if DB_SIGNING_KEY.exists():
        return serialization.load_pem_private_key(
            DB_SIGNING_KEY.read_bytes(), password=None
        )
    _pem = RSA.generate(1024).export_key()
    DB_SIGNING_KEY.write_bytes(_pem)
    return serialization.load_pem_private_key(_pem, password=None)


class CertManager(object):
    def __init__(self, db_path: str = USER_TLS_TOFU_DB.absolute()):
        self.db_path = db_path
        self.signing_key = load_db_signing_key()
        with sqlite3.connect(self.db_path) as con:
            cur = con.cursor()
            cur.execute(
                "CREATE TABLE IF NOT EXISTS keys (host TEXT, cert BLOB, sig BLOB)"
            )

    def add_cert(self, cert: bytes, address: str):
        sig = self.signing_key.sign(
            address.encode() + cert, padding.PKCS1v15(), hashes.SHA256()
        )
        with sqlite3.connect(self.db_path) as con:
            cur = con.cursor()
            cur.execute(
                "INSERT INTO keys VALUES (?, ?, ?)", (address, cert, sig)
            )

    def get_certs(self):
        with sqlite3.connect(self.db_path) as con:
            cur = con.cursor()
            cur.execute(
                "SELECT * FROM keys"
            )
            return cur.fetchall()

    def verify_cert(self, cert: bytes, address: str):
        for i in self.get_certs():
            if i[0] == address:
                self.signing_key.public_key().verify(
                    i[2], i[0].encode() + i[1], padding.PKCS1v15(), hashes.SHA256()
                )
                if i[1] == cert:
                    return True
                else:
                    raise CertMismatchError(
                        "The specified address has a certificate that does "
                        "not match that in the pre-existing database"
                    )
        raise CertNotFoundError(
            "The specified address was not located in the pre-existing "
            "database"
        )


cert_manager = CertManager()


class CertInvalidError(ssl.CertificateError):
    pass


class CertUntrustedError(ssl.CertificateError):
    pass


class CertDatetimeError(CertInvalidError):
    pass


class CertAddressError(CertInvalidError):
    pass


class CertMatchingError(CertUntrustedError):
    pass


class CertNotFoundError(CertUntrustedError):
    pass


class CertMismatchError(CertUntrustedError):
    pass


def validate_cert(cert: bytes, hostname: str = None):
    """
    Takes DER-encoded cert as returned from ssock.getpeercert(binary_form=True)
    and validates it, checking if it matches a given address (optional) and
    making sure that it's within the bounds in the `Validity' section of the
    cert.

    Inputs:
        cert: bytes
            The DER-encoded certificate to validate.

        hostname: str = None
            A hostname to match against. If it is falsey, no hostname checking
            is performed. If it is truthy, it is checked for equality against
            the subjectAltNames and commonName of the cert.

    Outputs:
        If the cert is valid for the hostname and current time, outputs `True'.
        Otherwise, raises an exception giving more detail.

    Raises:
        CertDatetimeError (subclass of CertInvalidError)
            This is raised if the supplied certificate is either past expiry
            or is not yet valid

        CertAddressError (subclass of CertInvalidError)
            This is raised if the supplied certificate has an invalid address
            in it's altNames or commonName

        CertMatchingError (subclass of CertUntrustedError)
            This is raised if the address supplied does not appear in the
            certificate's altNames or commonName
    """
    return_value = False

    parsed_cert = x509.load_der_x509_certificate(cert)
    now = datetime.datetime.utcnow()
    if parsed_cert.not_valid_before > now:
        raise CertDatetimeError(
            f"The supplied certificate is not valid until"
            f"{parsed_cert.not_valid_before}"
        )
    elif parsed_cert.not_valid_after < now:
        raise CertDatetimeError(
            f"The supplied certificate is not valid after"
            f"{parsed_cert.not_valid_after}"
        )

    if hostname:
        names = []
        ips = []
        cert_common_name = parsed_cert.subject.get_attributes_for_oid(
            x509.oid.NameOID.COMMON_NAME
        )[0].value
        names.append(cert_common_name)
        try:
            alt_names = parsed_cert.extensions.get_extension_for_oid(
                x509.oid.ExtensionOID.SUBJECT_ALTERNATIVE_NAME
            ).value
        except x509.ExtensionNotFound:
            pass
        else:
            alt_hostnames = alt_names.get_values_for_type(
                x509.DNSName
            )
            alt_ips = alt_names.get_values_for_type(
                x509.IPAddress
            )
            names.extend(alt_hostnames)
            ips.extend(alt_ips)

        try:  # If the hostname is an IP address...
            host_ip = ipaddress.ip_address(hostname)
        except ValueError:
            pass
        else:
            for i in ips:  # ... does it match one in the subjectAltNames?
                if ipaddress.ip_address(i) == host_ip:
                    return_value = True

        for i in names:
            # Is the cert's name or hostname an IDN?
            if i[:4] == "xn--" or hostname[:4] == "xn--":
                # If so, don't expand wildcards and match case-insensitively
                if hostname.lower() == i.lower():
                    return_value = True
            else:
                # get sections of a dNSName, as a left-most component and a
                # domain
                dns_name_components = i.split(".", 1)
                left_component = dns_name_components[0]
                if "*" in left_component:  # Is it a wildcard cert?
                    host_name_components = hostname.split(".", 1)

                    # Do the domain parts match?
                    if host_name_components[1] == dns_name_components[1]:
                        # If so, check the left-most component with wildcards
                        if left_component.count("*") > 1:
                            # If the dNSName has more than one asterisk, it's
                            # invalid
                            raise CertAddressError(
                                "The supplied certificate contains an invalid "
                                "dNSName containing two or more asterisks."
                            )
                        else:
                            # Use regex to detect matches
                            regex = left_component.replace(
                                "*",
                                "[A-Za-z0-9-]*"
                            ) + dns_name_components[1]
                            if re.match(regex, hostname):
                                return_value = True

                elif i == hostname:
                    return_value = True

        # If we got this far, no errors have been raised
        if return_value:
            return True
        else:
            # The cert isn't valid for the hostname
            raise CertMatchingError(
                "The supplied certificate is invalid for the supplied address"
            )

    return True

