@permission_required("is_staff", login_url='/dashboard/')
def gmail(request):
    state = "%06d" % random.randrange(10 ** 6)
    mailer.auth_state = state
    request.session['oauth_state'] = state
    auth_uri = urlsplit(mailer.auth_uri)
    query = [(key, value) for key, value in parse_qsl(auth_uri.query) if key != 'state']
    query.append(('state', state))
    return redirect(urlunsplit(auth_uri._replace(query=urlencode(query))))


