    pages = []
    res = fb_app.get("/{}/accounts".format(user_id))
    pages = [p for p in res.data.get("data")]
    while res.data.get("paging", {}).get("next"):
        res = fb_app.get(
            "/{}/accounts".format(user_id),
            data={
