def search(request):
    query = request.GET.get('searchQuery', '')
    results = []
    count = 0
    if(query):
        results = Blog.objects.filter(
            Q(title__contains=query) |
            Q(text__contains=query)
        )
        count = results.count()
    response = render(request, 'blog/results.html', context={'results':results, 'count':count})
    response.content += mark_safe('<p class="search-query">Matching blog posts for: ' + query + '</p>').encode('utf-8')
    return response


@login_required
def post_new(request):
    print(request.__dict__)
    if request.method == "POST":
        form = PostForm(request.POST)
        if form.is_valid():
            post = form.save(commit=False)
            # post.author = User.objects.get(username=request.username)
            post.author = request.user
            post.published_date = timezone.now()
            post.save()
            return redirect('post_detail', pk=post.pk)
    else:
        form = PostForm()
    return render(request, 'blog/post_edit.html', {'form': form})

